5	namespace App\Legacy\Report;
6	
7	use App\Legacy\lib\LegacyDb;
8	
9	/**
10	 * Tržby za měsíc pro report staré administrace, s typy a bez globálního stavu.
11	 *
12	 * Počítá záměrně stejně jako dřívější funkce monthlyRevenue() v lib/revenue.php:
13	 * jen zaplacené objednávky (stav paid), bez slevy na objednávku, cizí měny přes
14	 * kurz v exchange_rates. Chování hlídají charakterizační testy v tests/Legacy.
15	 */
16	final readonly class MonthlyRevenue
17	{
18	    public function __construct(
19	        private LegacyDb $db,
20	    ) {}
21	
22	    /** Tržby v CZK naformátované jako „1 200,00“. */
23	    public function forMonth(string $month): string
24	    {
25	        $sum = 0;
26	        foreach ($this->paidItems($month) as $item) {
27	            $line = $item['unitPrice'] * $item['quantity'];
28	            if ($item['currency'] !== 'CZK') {
29	                $line = $this->toCzk($line, $item['currency']);
30	            }
31	            $sum += $line;
32	        }
33	
34	        // Haléře na koruny, zaokrouhlení na dvě místa jako dřív.
35	        $sum = round($sum / 100, 2);
36	
37	        return number_format($sum, 2, ',', ' ');
38	    }
39	
40	    /** @return list<array{unitPrice: int, quantity: int, currency: string}> */
41	    private function paidItems(string $month): array
42	    {
43	        $rows = $this->db->query(
44	            'SELECT i.unit_price_amount_in_cents AS unitPrice, i.quantity AS quantity, i.unit_price_currency AS currency'
45	            .' FROM order_items i JOIN orders o ON o.id = i.order_id'
46	            ." WHERE o.status = 'paid' AND strftime('%Y-%m', o.placed_at) = ".$this->db->quote($month),
47	        );
48	
49	        $items = [];
50	        foreach (is_array($rows) ? $rows : [] as $row) {
51	            if (!is_array($row) || !is_numeric($row['unitPrice'] ?? null) || !is_numeric($row['quantity'] ?? null) || !is_string($row['currency'] ?? null)) {
52	                throw new \UnexpectedValueException('Unexpected row in order_items.');
53	            }
54	            $items[] = ['unitPrice' => (int) $row['unitPrice'], 'quantity' => (int) $row['quantity'], 'currency' => $row['currency']];
55	        }
56	
57	        return $items;
58	    }
59	
60	    private function toCzk(int|float $cents, string $currency): int|float
61	    {
62	        $rate = $this->db->value('SELECT rate_to_czk FROM exchange_rates WHERE currency = '.$this->db->quote($currency));
63	
64	        // Neznámá měna se bere jako CZK (stejně jako dřív).
65	        return is_numeric($rate) ? $cents * (float) $rate : $cents;
66	    }
67	}
