62	    public function detailAction()
63	    {
64	        global $db;
65	        legacy_db();
66	
67	        $id = get_param('id');
68	        $order = $db->one("SELECT * FROM orders WHERE id = '" . $id . "'");
69	        if ($order === null) {
70	            return $this->notFound('Objednávka ' . $id . ' neexistuje');
71	        }
72	
73	        $items = $db->query("SELECT i.*, p.name, p.sku FROM order_items i LEFT JOIN products p ON p.id = i.product_id WHERE i.order_id = '" . $id . "' ORDER BY i.id");
74	        $customer = $db->one("SELECT * FROM customers WHERE id = '" . $order['customer_id'] . "'");
75	        $notes = $db->query("SELECT * FROM order_notes WHERE order_id = '" . $id . "' ORDER BY created_at DESC");
76	        $invoice = $db->one("SELECT * FROM invoices WHERE order_id = '" . $id . "'");
77	        $history = $db->query("SELECT * FROM audit_log WHERE entity = 'order' AND entity_id = '" . $id . "' ORDER BY created_at DESC LIMIT 50");
78	
79	        $sum = 0;
80	        foreach ($items as $it) {
81	            $sum += $it['quantity'] * $it['unit_price_amount_in_cents'];
82	        }
83	
84	        return $this->renderLayout('orders/detail', array(
85	            'order'    => $order,
86	            'items'    => $items,
87	            'customer' => $customer,
88	            'notes'    => $notes,
89	            'invoice'  => $invoice,
90	            'history'  => $history,
91	            'sum'      => $sum,
92	            'toPay'    => max(0, $sum - (int) $order['discount_amount_in_cents']),
93	        ), 'Objednávka ' . $id);
94	    }
