public function paidOrderCanBeCancelledAndStockIsReleased(): void
{
    $orders = self::getContainer()->get(OrderRepository::class);
    $stockItems = self::getContainer()->get(StockItemRepository::class);
    $keyboard = Catalog::KEYBOARD;

    $order = Order::place(OrderId::generate(), CustomerId::generate());
    $order->addItem(
        \App\Ordering\Domain\ValueObject\ProductId::fromString($keyboard),
        3,
        new Money(500_00, Currency::CZK),
    );
    $order->confirm();
    $order->markPaid();
    $orders->save($order);

    $initialAvailable = $stockItems->get(
        \App\Ordering\Domain\ValueObject\ProductId::fromString($keyboard),
    )->available();

    $this->client->request(
        'POST',
        '/admin/legacy/order_edit?id='.$order->id->value,
        ['status' => 'cancelled'],
        [],
        ['HTTP_X-CSRF-TOKEN' => $this->getCsrfToken()],
    );
    $this->client->followRedirect();
    self::assertSelectorTextContains('.flash', 'stornována');

    self::getContainer()->get(EntityManagerInterface::class)->clear();
    $cancelled = $orders->get($order->id);
    self::assertSame(OrderStatus::Cancelled, $cancelled->status);
    $releasedAvailable = $stockItems->get(
        \App\Ordering\Domain\ValueObject\ProductId::fromString($keyboard),
    )->available();
    self::assertSame($initialAvailable + 3, $releasedAvailable);
}

