private function getCsrfToken(): string
{
    $this->client->request('GET', '/admin/legacy/order_edit?id=test');
    $crawler = $this->client->getCrawler();
    return $crawler->filter('input[name="_csrf_token"]')->attr('value') ?? '';
}

